import sympy

def solve():
    # We want to find the number of positive integers n such that S(n) = 11.
    # S(n) is the smallest k such that f^k(n) = 1.
    # This means f^11(n) = 1 and f^k(n) != 1 for k < 11.

    # Let A_k be the set of integers n such that S(n) = k.
    # A_0 = {1}
    # f(n) = n/2 if n is even, n+1 if n is odd.
    # To find A_{k+1}, we find n such that f(n) = m for m in A_k, and n is not in A_j for j <= k.

    # If f(n) = m:
    # 1. n/2 = m => n = 2m (always even)
    # 2. n+1 = m => n = m-1 (must be odd)

    # Let's track the sets A_k.
    # A_0 = {1}
    current_set = {1}
    all_visited = {1}

    for k in range(1, 12):
        next_set = set()
        for m in current_set:
            # Case 1: n = 2m
            n1 = 2 * m
            if n1 not in all_visited:
                next_set.add(n1)

            # Case 2: n = m - 1
            n2 = m - 1
            if n2 > 0 and n2 % 2 != 0:
                if n2 not in all_visited:
                    next_set.add(n2)

        current_set = next_set
        all_visited.update(next_set)

    # The answer is the size of A_11.
    print(f"ANSWER: {len(current_set)}")

if __name__ == "__main__":
    solve()
