import itertools

def solve():
    # A 4x4 grid has 16 cells.
    # We can represent the placement of coins as a bitmask of 16 bits.
    # Grid indexing: (r, c) -> r * 4 + c

    # Precompute adjacency for the "no two coins are orthogonally adjacent" rule
    adj = []
    for r in range(4):
        for c in range(4):
            neighbors = []
            if r > 0: neighbors.append((r-1)*4 + c)
            if r < 3: neighbors.append((r+1)*4 + c)
            if c > 0: neighbors.append(r*4 + (c-1))
            if c < 3: neighbors.append(r*4 + (c+1))
            adj.append(neighbors)

    # Precompute 2x2 squares
    # There are (4-1) * (4-1) = 9 such squares.
    squares = []
    for r in range(3):
        for c in range(3):
            sq = [
                r*4 + c, r*4 + (c+1),
                (r+1)*4 + c, (r+1)*4 + (c+1)
            ]
            squares.append(sq)

    count = 0
    # Brute force all 2^16 possible configurations
    for i in range(1 << 16):
        # Rule 1: No two coins are orthogonally adjacent
        valid_adj = True
        for cell in range(16):
            if (i >> cell) & 1:
                for neighbor in adj[cell]:
                    if (i >> neighbor) & 1:
                        valid_adj = False
                        break
            if not valid_adj:
                break

        if not valid_adj:
            continue

        # Rule 2: Each 2x2 square has at least one coin
        valid_sq = True
        for sq in squares:
            has_coin = False
            for cell in sq:
                if (i >> cell) & 1:
                    has_coin = True
                    break
            if not has_coin:
                valid_sq = False
                break

        if valid_sq:
            count += 1

    return count

if __name__ == "__main__":
    result = solve()
    print(f"ANSWER: {result}")
